    <div class="container page-head">
      <h1>Pricing</h1>
      <p class="lede">A monthly box of desk things. Change or cancel any time.</p>
    </div>

    <section class="section">
      <div class="container">
        <div class="plans">
          <div class="plan">
            <h2 class="plan-name">Starter</h2>
            <p class="plan-price">$9<small> / month</small></p>
            <p class="muted">For one desk.</p>
            <ul class="plan-features">
              <li>One item a month</li>
              <li>Free shipping</li>
              <li>Cancel any time</li>
            </ul>
            <a class="btn btn-secondary" href="contact.html">Choose Starter</a>
          </div>
          <div class="plan plan-featured">
            <span class="plan-ribbon">Most popular</span>
            <h2 class="plan-name">Pro</h2>
            <p class="plan-price">$19<small> / month</small></p>
            <p class="muted">For people who work from home.</p>
            <ul class="plan-features">
              <li>Three items a month</li>
              <li>Free shipping and returns</li>
              <li>Early access to new products</li>
            </ul>
            <a class="btn btn-primary" href="contact.html">Choose Pro</a>
          </div>
          <div class="plan">
            <h2 class="plan-name">Team</h2>
            <p class="plan-price">$49<small> / month</small></p>
            <p class="muted">For a small office.</p>
            <ul class="plan-features">
              <li>Ten items a month</li>
              <li>One invoice for everyone</li>
              <li>A named contact</li>
            </ul>
            <a class="btn btn-secondary" href="contact.html">Choose Team</a>
          </div>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <h2 class="section-title">Compare plans</h2>
        <div class="table-wrap">
          <table class="table">
            <thead>
              <tr>
                <th>Feature</th>
                <th>Starter</th>
                <th>Pro</th>
                <th>Team</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>Items a month</td>
                <td>1</td>
                <td>3</td>
                <td>10</td>
              </tr>
              <tr>
                <td>Free returns</td>
                <td>No</td>
                <td>Yes</td>
                <td>Yes</td>
              </tr>
              <tr>
                <td>Early access</td>
                <td>No</td>
                <td>Yes</td>
                <td>Yes</td>
              </tr>
              <tr>
                <td>Invoices</td>
                <td>Per order</td>
                <td>Per order</td>
                <td>Monthly</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <h2 class="section-title">Questions</h2>
        <div class="faq">
          <div class="faq-item">
            <h3>Can I skip a month?</h3>
            <p>Yes. Skip as often as you like from your orders page.</p>
          </div>
          <div class="faq-item">
            <h3>What if I do not like an item?</h3>
            <p>Send it back within thirty days and we refund it.</p>
          </div>
          <div class="faq-item">
            <h3>Do you ship abroad?</h3>
            <p>We ship to most of Europe and North America.</p>
          </div>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <p>© 2026 Acme Storefront. Small things for busy desks.</p>
      <div class="footer-links">
        <a href="about.html">About</a>
        <a href="contact.html">Contact</a>
      </div>
    </div>
  </footer>

  <script src="js/app.js"></script>
</body>
